'use strict';
const registration=/(?:^|\/)register(?:\.html)?\/?$/.test(location.pathname),element=id=>document.getElementById(id);
const accountCopy={
vi:{headline:'Một chút mỗi ngày. Tiếng Đức tiến xa.',intro:'Đăng nhập để bắt đầu học, lưu tài liệu và theo dõi hành trình của riêng bạn.',login:'Đăng nhập',register:'Tạo tài khoản',subtitle:'Chào mừng bạn đến với Elio Einfach.',username:'Tên đăng nhập',usernameHelp:'2–32 ký tự: chữ không dấu, số, dấu _ hoặc -.',password:'Mật khẩu',confirm:'Nhập lại mật khẩu',showPassword:'Hiện mật khẩu',newPrompt:'Chưa có tài khoản?',oldPrompt:'Đã có tài khoản?',signup:'Đăng ký',signin:'Đăng nhập',localNote:'Tài khoản chỉ dùng trên trình duyệt này. Mật khẩu từ 4–128 ký tự; không dùng mật khẩu quan trọng.',usernameError:'Tên đăng nhập phải có 2–32 ký tự: chữ không dấu, số, _ hoặc -.',passwordError:'Mật khẩu cần từ 4–128 ký tự.',existsError:'Tên đăng nhập đã tồn tại. Hãy chọn tên khác hoặc đăng nhập.',invalidError:'Tên đăng nhập hoặc mật khẩu chưa đúng.',confirmError:'Hai mật khẩu chưa khớp.',storageError:'Không thể lưu tài khoản. Hãy kiểm tra quyền lưu trữ hoặc dung lượng trình duyệt.',busy:'Đang xử lý…'},
en:{headline:'A little every day. A world of German.',intro:'Sign in to learn, save materials and track your own progress.',login:'Sign in',register:'Create an account',subtitle:'Welcome to Elio Einfach.',username:'Username',usernameHelp:'2–32 characters: letters, numbers, _ or -.',password:'Password',confirm:'Confirm password',showPassword:'Show password',newPrompt:'New here?',oldPrompt:'Already have an account?',signup:'Sign up',signin:'Sign in',localNote:'Accounts are stored in this browser only. Use 4–128 characters and avoid an important password.',usernameError:'Use 2–32 letters, numbers, _ or -.',passwordError:'Password must contain 4–128 characters.',existsError:'Username already exists. Choose another or sign in.',invalidError:'Incorrect username or password.',confirmError:'Passwords do not match.',storageError:'Cannot save your account. Check browser storage permissions or available space.',busy:'Please wait…'},
de:{headline:'Jeden Tag ein bisschen. Deutsch wird einfacher.',intro:'Melde dich an, um zu lernen, Materialien zu speichern und deinen Fortschritt zu verfolgen.',login:'Anmelden',register:'Konto erstellen',subtitle:'Willkommen bei Elio Einfach.',username:'Benutzername',usernameHelp:'2–32 Zeichen: Buchstaben, Zahlen, _ oder -.',password:'Passwort',confirm:'Passwort wiederholen',showPassword:'Passwort anzeigen',newPrompt:'Noch kein Konto?',oldPrompt:'Schon registriert?',signup:'Registrieren',signin:'Anmelden',localNote:'Konten werden nur in diesem Browser gespeichert. Verwende 4–128 Zeichen und kein wichtiges Passwort.',usernameError:'Verwende 2–32 Buchstaben, Zahlen, _ oder -.',passwordError:'Das Passwort muss 4–128 Zeichen enthalten.',existsError:'Dieser Benutzername existiert bereits. Wähle einen anderen oder melde dich an.',invalidError:'Benutzername oder Passwort falsch.',confirmError:'Die Passwörter stimmen nicht überein.',storageError:'Das Konto kann nicht gespeichert werden. Prüfe Browser-Speicher und Berechtigungen.',busy:'Bitte warten…'}
};
let accountLanguage=localStorage.getItem('dt:_language')||'vi',accountBusy=false;
const next=Account.destination(new URLSearchParams(location.search).get('next'));
function applyAccountPage(){if(!accountCopy[accountLanguage])accountLanguage='vi';const c=accountCopy[accountLanguage];document.documentElement.lang=accountLanguage;document.title='Elio Einfach · '+(registration?c.register:c.login);const values={...c,title:registration?c.register:c.login,submit:registration?c.register:c.login,switchPrompt:registration?c.oldPrompt:c.newPrompt,switchLink:registration?c.signin:c.signup};document.querySelectorAll('[data-account]').forEach(el=>el.textContent=values[el.dataset.account]||'');element('account-language').value=accountLanguage;element('account-switch').href=(registration?'login.html':'register.html')+'?next='+encodeURIComponent(next);document.body.classList.toggle('dark',localStorage.getItem('dt:_theme')==='dark');}
element('account-language').onchange=e=>{accountLanguage=e.target.value;localStorage.setItem('dt:_language',accountLanguage);element('account-error').textContent='';applyAccountPage();};
element('account-theme').onclick=()=>{localStorage.setItem('dt:_theme',document.body.classList.contains('dark')?'light':'dark');applyAccountPage();};
element('account-show-password').onchange=e=>{for(const id of ['account-password','account-confirm'])if(element(id))element(id).type=e.target.checked?'text':'password';};
element('account-form').onsubmit=async e=>{e.preventDefault();if(accountBusy)return;const c=accountCopy[accountLanguage],password=element('account-password').value;element('account-error').textContent='';if(registration&&password!==element('account-confirm').value){element('account-error').textContent=c.confirmError;element('account-confirm').focus();return;}accountBusy=true;element('account-submit').disabled=true;element('account-submit').textContent=c.busy;try{await Account.authenticate(element('account-username').value,password,registration);element('account-password').value='';if(element('account-confirm'))element('account-confirm').value='';location.replace(next);}catch(error){element('account-error').textContent=c[error.message+'Error']||c.storageError;}finally{accountBusy=false;element('account-submit').disabled=false;applyAccountPage();}};
applyAccountPage();if(Account.current())location.replace(next);
